import {
  Component,
  ComponentInterface,
  Element,
  Host,
  Prop,
  Event,
  h,
  EventEmitter,
  Watch,
  State,
  VNode,
} from '@stencil/core';
import type { ThumbnailSize, ThumbnailAction } from './types';
import { noop } from 'lodash-es';
import { Slot, Slots } from '@src/framework/decorators';
import classnames from 'classnames';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { asObject } from '@src/shared/type-utils';
import { KsDropdownMenu } from '../ks-dropdown-menu';
import {
  KsIconAiGeneration,
  KsIconBlockNone,
  KsIconMoreVertical,
  KsIconOverlayPause,
  KsIconOverlayPlay,
} from '@fe-infra/keystone-icons-stencil';

const prefix = 'thumbnail';
const GRID_MORE_THRESHOLD = 2;

/**
 * @slot icon - Slot for a custom icon. Rendered as an overlay on top of the main images/content.
 */
@Component({
  tag: 'ks-thumbnail',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsThumbnail implements ComponentInterface {
  @Element() el!: HTMLKsThumbnailElement;

  /** Thumbnail size. Can be 'xs', 'sm', 'md', 'lg', 'xl'. */
  @Prop() size: ThumbnailSize = 'md';
  /** The aspect ratio of the component. Can be '1:1', '2:3', '3:2'. */
  @Prop() ratio: '1:1' | '2:3' | '3:2' = '1:1';
  /** Specifies how the background image (if provided via `image` prop) should be resized to fit its container. Can be 'cover' or 'contain'. */
  @Prop() objectFit: 'cover' | 'contain' = 'cover';
  /** The image URL. If provided, it will be used as the background of the thumbnail. */
  @Prop() src?: string;
  /** The alt text for the image. */
  @Prop() alt?: string;
  /** A list of image items to display. Will override the `src` prop if provided. */
  @Prop() items?: (string | { src: string; alt?: string })[];
  /**  A list of actions (tools) to display. If more than one action is provided, a 'more' icon will be shown to access them via a dropdown. Not rendered if `block` prop is true. */
  @Prop() actions: ThumbnailAction[] = [];
  /** If true, displays a GenAI icon badge in the bottom-left corner. */
  @Prop() showGenAIBadge = false;
  /** Whether to display a play button icon. If true, and the component is not `block` or `disabled`, clicking the play icon emits the `ksPlay` event. */
  @Prop() playable = false;
  /** Whether to display a pause button icon. If true, and the component is not `block` or `disabled`, clicking the play icon emits the `ksPause` event. */
  @Prop() playing = false;
  /** If true, the component is visually styled as disabled, and the play button (if `playable` is true) will not be shown. */
  @Prop() disabled = false;
  /** If true, the component displays a blocked state overlay. The `icon` slot, `playable` icon, and `actions` will not be rendered. */
  @Prop() blocked: boolean | { reason: string } = false;

  /** Indicates if the thumbnail represents stacked items, rendering a visual stacking shadow effect. This effect is only applied when `size` is 'md', 'lg' or 'xl'. */
  @Prop() stacked = false;

  @State() actionSource: KsDropdownMenu['options'] = [];
  @State() private actionMenuOpen = false;

  /** Slot for a custom icon. Rendered only if `block` is false and content is provided to this slot. */
  @Slot({ slotname: 'icon' }) private iconSlot?: Slots;

  /** Emitted when the play icon is clicked. The play icon is only visible if `playable` is true, and `block` and `disabled` are false. */
  @Event({ bubbles: false, composed: false }) ksPlayingChange!: EventEmitter<boolean>;

  @Watch('disabled')
  disabledWatcher() {
    this.setIcon();
  }

  @Watch('size')
  handleSizeChange() {
    this.setIcon();
  }

  constructor() {
    registerPluginManager(this.el);
  }

  private get _images() {
    if (this.items?.length) {
      const items = this.items.map((item) => (typeof item === 'string' ? { src: item } : item));

      if (items.length > 1 && (this.size === 'xl' || this.size === 'lg') && this.ratio === '1:1') {
        return items.slice(0, 4);
      }
      return items.slice(0, 1);
    } else if (this.src) {
      return [{ src: this.src, alt: this.alt }];
    } else {
      return [];
    }
  }

  private observer?: MutationObserver;

  private getPlaySize() {
    switch (this.size) {
      case 'xs':
      case 'sm':
        return 16;
      case 'xl':
        return 32;
      default:
        return 24;
    }
  }

  private setIcon() {
    let size = 24;
    switch (this.size) {
      case 'xs':
        size = 14;
        break;
      case 'sm':
        size = 16;
        break;
      case 'md':
        size = 24;
        break;
      case 'lg':
        size = 32;
        break;
      case 'xl':
        size = 48;
        break;
      default:
        size = 24;
        break;
    }

    if (this.iconSlot?.[0]) {
      if (this.iconSlot[0].tagName === 'KS-ICON') {
        this.iconSlot[0].setAttribute('size', `${size}px`);
      } else if (this.iconSlot[0].children[0]?.tagName === 'KS-ICON') {
        this.iconSlot[0].children[0].setAttribute('size', `${size}px`);
      }
    }
  }

  private getBlockSize() {
    switch (this.size) {
      case 'xs':
        return 14;
      case 'sm':
      case 'md':
        return 16;
      case 'lg':
        return 24;
      case 'xl':
        return 32;
      default:
        return 16;
    }
  }

  private renderBadges() {
    if (this.size !== 'xl' || !this.showGenAIBadge) return null;

    return (
      <div class={`${prefix}__badges`}>
        <span
          class={{
            badge: true,
            'badge--icon': true,
          }}
        >
          <KsIconAiGeneration size={14}></KsIconAiGeneration>
        </span>
      </div>
    );
  }

  private reduceActions() {
    return this.actions.map((item, index) => {
      const hasIcon = typeof item.icon === 'function';
      const hasLabel = typeof item.label === 'function';
      const option: NonNullable<KsDropdownMenu['options']>[number] = {
        value: index,
        disabled: item.disabled,
        onClick: item.onClick,
      };
      if (hasIcon && !hasLabel) {
        option.label = item.icon;
      } else {
        if (hasIcon) {
          option.prefix = item.icon;
        }
        if (hasLabel) {
          option.label = item.label;
        }
      }
      return option;
    });
  }
  componentWillLoad() {
    this.actionSource = this.reduceActions();
  }
  @Watch('actions')
  actionsWatcher() {
    this.actionSource = this.reduceActions();
    if (this.actions.length <= 1) {
      this.actionMenuOpen = false;
    }
  }

  componentDidLoad() {
    this.setIcon();
    this.observer = new MutationObserver(() => {
      this.setIcon();
    });
    this.observer.observe(this.el, {
      childList: true,
    });
  }

  disconnectedCallback() {
    setTimeout(() => {
      if (!this.el?.isConnected) {
        this.observer?.disconnect();
      }
    });
  }

  // FIXME buggy behavior in Vue
  componentWillRender() {
    if (this.actions?.length === 1) {
      const dynamicSlots: unknown[] = [];

      this.actions.forEach(({ icon }, index: number) => {
        if (typeof icon === 'function') {
          dynamicSlots.push(this.wrapWithSlot(`icon-${index}`, icon()));
        }
      });
      this.setDynamicRenderDeps(dynamicSlots);
    }
  }

  private handlePlayingChange(nextPlaying: boolean) {
    this.ksPlayingChange.emit(nextPlaying);
  }

  private handlePlayClick = () => {
    this.handlePlayingChange(true);
  };

  private handlePauseClick = () => {
    this.handlePlayingChange(false);
  };

  private handleActionMenuOpenChange({ detail }: CustomEvent<boolean>) {
    this.actionMenuOpen = detail;
  }

  private handleDropdownOpenChange = (event: CustomEvent<boolean>) => {
    this.handleActionMenuOpenChange(event);
  };

  private handleDropdownDynamicRenderDeps(children: unknown[], getPassThroughSlots?: () => VNode[]) {
    this.setDynamicRenderDeps(children);
    this.passThroughSlots = getPassThroughSlots?.() || [];
  }

  private handleDropdownSetDynamicRenderDeps = (children: unknown[], getPassThroughSlots?: () => VNode[]) => {
    this.handleDropdownDynamicRenderDeps(children, getPassThroughSlots);
  };

  private isActionable() {
    return !this.disabled && !this.blocked && this.actions.length > 0;
  }

  private handleContainerMouseEnter = () => {
    if (this.actions.length <= 1 || !this.isActionable()) {
      return;
    }

    this.actionMenuOpen = true;
  };

  private handleContainerMouseLeave = () => {
    if (this.actions.length <= 1) {
      return;
    }

    this.actionMenuOpen = false;
  };

  private handleContainerClick = () => {
    if (!this.isActionable()) {
      return;
    }

    if (this.actions.length === 1) {
      this.actions[0]?.onClick?.();
      return;
    }

    this.actionMenuOpen = true;
  };

  render() {
    const containerStyle = {
      background:
        this._images.length === 1
          ? `url(${this._images[0]?.src}) 50% / ${this.objectFit} no-repeat`
          : `var(--ks-color-neutral-surface2${this.disabled ? 'Disabled' : ''})`,
    };

    const ratio = this.ratio === '2:3' ? 'horizontal' : this.ratio === '3:2' ? 'vertical' : '';

    const cls = classnames(`${prefix}__container`, `${prefix}__${ratio}`, {
      [`${prefix}__${this.size}`]: true,
    });

    const isStacked = this.stacked && (this.size === 'lg' || this.size === 'xl' || this.size === 'md');

    return (
      <Host class="KsThumbnail">
        <div class={cls}>
          {isStacked && (
            <div class={`${prefix}__showStack ${prefix}__showStack-${this.size} ${prefix}__showStack-${ratio}`}>
              <div class={`${prefix}__stack-line`} />
              <div class={`${prefix}__stack-line`} />
            </div>
          )}

          <div
            class={classnames(prefix, {
              [`${prefix}__disabled`]: this.disabled,
              [`${prefix}__block`]: this.blocked,
              [`${prefix}__actionable`]: this.isActionable(),
            })}
            style={containerStyle}
            onClick={this.handleContainerClick}
            onMouseEnter={this.handleContainerMouseEnter}
            onMouseLeave={this.handleContainerMouseLeave}
          >
            {!this.blocked && this.iconSlot && <slot name="icon"></slot>}
            {!this.blocked && this.renderBadges()}
            {!this.blocked &&
              this.playable &&
              !this.disabled &&
              (this.playing ? (
                <KsIconOverlayPause
                  class={`${prefix}__pause-icon`}
                  onClick={this.handlePauseClick}
                  size={this.getPlaySize()}
                  data-testid="ks-thumbnail-index-wJiTEo"
                />
              ) : (
                <KsIconOverlayPlay
                  onClick={this.handlePlayClick}
                  size={this.getPlaySize()}
                  data-testid="ks-thumbnail-index-taorrS"
                />
              ))}

            {!this.blocked && (this.actions.length || this.playable) && (
              <div class={`${prefix}__mask`}>
                {this.actions.length > 1 ? (
                  <ks-dropdown-menu
                    style={{ justifyContent: 'center' }}
                    selectable={false}
                    options={this.actionSource}
                    open={this.actionMenuOpen}
                    popoverProps={{ trigger: 'manual' }}
                    onKsOpenChange={this.handleDropdownOpenChange}
                    wrapWithSlot={this.wrapWithSlot}
                    setDynamicRenderDeps={this.handleDropdownSetDynamicRenderDeps}
                    popupWidth={'auto'}
                  >
                    <KsIconMoreVertical color="white"></KsIconMoreVertical>
                    {this.passThroughSlots}
                  </ks-dropdown-menu>
                ) : (
                  <slot name="icon-0" data-testid={`ks-thumbnail-index-0`}></slot>
                )}
              </div>
            )}

            {this.blocked && (
              <ks-tooltip size="sm" disabled={!asObject(this.blocked)?.reason} content={asObject(this.blocked)?.reason}>
                <div class={`${prefix}__block-container`}>
                  <KsIconBlockNone class={'block-icon'} size={this.getBlockSize()}></KsIconBlockNone>
                </div>
              </ks-tooltip>
            )}

            {this._images.length > 1 && (
              <div
                class={{
                  [`${prefix}__grid`]: true,
                  [`${prefix}__grid__more`]: this._images.length > GRID_MORE_THRESHOLD,
                }}
              >
                {this._images.map((img, index) => (
                  <img
                    key={`${img}-${index}`}
                    class={`${prefix}__grid__img`}
                    src={img.src}
                    alt={img.alt}
                    data-testid={`ks-thumbnail-index-b6v4vn-${`${img}-${index}`}`}
                  />
                ))}
              </div>
            )}
          </div>
        </div>
      </Host>
    );
  }

  @State() private passThroughSlots: VNode[] = [];
  /**
   * @private
   */
  @Prop() wrapWithSlot: (slotName: string, children: unknown) => unknown = () => [];
  /**
   * @private
   */
  @Prop() setDynamicRenderDeps: (children: unknown[]) => void = noop;
}
